 43	predicate Ascending(q: seq<int>)
 44	{
 45		forall i,j :: 0 <= i < j < |q| ==> q[i] < q[j]
 46	}
 47	
 48	predicate NoDuplicates(q: seq<int>) { forall i,j :: 0 <= i < j < |q| ==> q[i] != q[j] }
 49	
 50	/*
 51		Goal: Implement correctly, clearly. No need to document the proof obligations.
 52	*/
 53	method BuildBST(q: seq<int>) returns (t: Tree)
 54		requires NoDuplicates(q)
 55		ensures BST(t) && NumbersInTree(t) == NumbersInSequence(q)
 56	{
 57		t := Empty;
 58		for i:=0 to |q|
 59			invariant BST(t);
 60			invariant NumbersInTree(t) == NumbersInSequence(q[..i])
 61		{
 62			t := InsertBST(t,q[i]);
 63		}
 64	}
 65	
 66	/*
 67		Goal: Implement correctly, efficiently, clearly, documenting the proof obligations
 68		as we've learned, with assertions and a lemma for each proof goal
 69	*/
 70	method InsertBST(t0: Tree, x: int) returns (t: Tree)
 71		requires BST(t0) && x !in NumbersInTree(t0)
 72		ensures BST(t) && NumbersInTree(t) == NumbersInTree(t0)+{x}
 73	{
 74		match t0 
 75		{
 76			case Empty => t := Node(x, Empty, Empty);
 77	
 78			case Node(i, left, right) => 
 79			{
 80				var tmp:Tree:= Empty;
 81				if x < i
 82				{
 83					LemmaBinarySearchSubtree(i,left,right);
 84					tmp :=  InsertBST(left, x);
 85					t := Node(i, tmp, right);
 86					ghost var right_nums := Inorder(right);
 87					ghost var left_nums := Inorder(left);
 88					ghost var all_nums := Inorder(t0);
 89					assert all_nums == left_nums + [i] + right_nums;
 90					assert all_nums[|left_nums|] == i;
 91					assert all_nums[|left_nums|+1..] == right_nums;
 92					// assert all_nums[..|left_nums|] == left_nums;
 93					assert Ascending(right_nums);
 94					assert Ascending(left_nums);
 95					assert Ascending(left_nums + [i] + right_nums);
 96					assert forall j,k :: |left_nums| < j < k < |all_nums| ==> x < i < all_nums[j] < all_nums[k];
 97					ghost var new_all_nums := Inorder(t);
 98					ghost var new_left_nums := Inorder(tmp);
 99					assert new_all_nums == (new_left_nums + [i] + right_nums);
100					assert Ascending([i]+right_nums);
101					assert Ascending(new_left_nums);
102					assert NumbersInSequence(new_left_nums) == NumbersInSequence(left_nums) + {x};
103					// assert Ascending(new_left_nums+ [i] + right_nums);
104	
105	
106					assert forall j,k::0<= j < k <|all_nums| ==> all_nums[j]<all_nums[k];
107					assert forall j,k::0<= j < k <|left_nums| ==> all_nums[j]<all_nums[k]<all_nums[|left_nums|];
108					assert all_nums[|left_nums|] == i;
109					assert left_nums == all_nums[..|left_nums|];
110					assert NumbersInSequence(new_left_nums) == NumbersInSequence(all_nums[..|left_nums|])+{x};
111					assert forall j,k::0<=j < k < |left_nums| ==> left_nums[j] < left_nums[k] < i;
112					assert x < i;
113	
114					assert forall j :: j in NumbersInSequence(all_nums[..|left_nums|]) ==> j < i;
115					assert forall j :: j in NumbersInSequence(all_nums[..|left_nums|])+{x} ==> j < i;
116					
117					assert forall j :: j in NumbersInSequence(new_left_nums) ==> j < i;
118					assert forall j :: j in NumbersInSequence(new_left_nums) <==> j in new_left_nums;
119					
120					assert forall j,k::0<=j < k < |new_left_nums| ==> new_left_nums[j] < new_left_nums[k];
121					assert x < i;
122					lemma_all_small(new_left_nums,i);
123					assert forall j::0<=j < |new_left_nums| ==> new_left_nums[j] < i;
124					
125					assert Ascending(new_left_nums+[i]);
126					assert Ascending(Inorder(t));
127	
128					assert BST(t);
129				}
130				else
131				{
132					LemmaBinarySearchSubtree(i,left,right);
133					tmp := InsertBST(right, x);
134					t := Node(i, left, tmp);
135	
136					ghost var right_nums := Inorder(right);
137					ghost var left_nums := Inorder(left);
138					ghost var all_nums := Inorder(t0);
139					assert all_nums == left_nums + [i] + right_nums;
140					assert all_nums[|left_nums|] == i;
141					assert all_nums[|left_nums|+1..] == right_nums;
142					// assert all_nums[..|left_nums|] == left_nums;
143					assert Ascending(right_nums);
144					assert Ascending(left_nums);
145					assert Ascending(left_nums + [i] + right_nums);
146					assert forall j,k :: 0 <= j < k < |left_nums| ==> all_nums[j] < all_nums[k] < i < x;
147					ghost var new_all_nums := Inorder(t);
148					ghost var new_right_nums := Inorder(tmp);
149					assert new_all_nums == (left_nums + [i] + new_right_nums);
150					assert Ascending(left_nums + [i]);
151					assert Ascending(new_right_nums);
152					assert NumbersInSequence(new_right_nums) == NumbersInSequence(right_nums) + {x};
153					// assert Ascending(left_nums+ [i] + right_nums);
154	
155					assert forall j,k::0<= j < k <|all_nums| ==> all_nums[j]<all_nums[k];
156					assert forall j,k::|left_nums| < j < k < |all_nums|==> all_nums[|left_nums|]<all_nums[j]<all_nums[k];
157					assert all_nums[|left_nums|] == i;
158					assert left_nums == all_nums[..|left_nums|];
159					assert NumbersInSequence(new_right_nums) == NumbersInSequence(all_nums[|left_nums|+1..])+{x};
160					assert forall j,k::0<=j < k < |right_nums| ==> i < right_nums[j] < right_nums[k] ;
161					assert x > i;
162	
163					// assert forall j :: j in NumbersInSequence(all_nums[|left_nums|+1..]) ==> j > i;
164					// assert forall j :: j in NumbersInSequence(all_nums[|left_nums|+1..])+{x} ==> j > i;
165					
166					assert forall j :: j in NumbersInSequence(new_right_nums) ==> j > i;
167					assert forall j :: j in NumbersInSequence(new_right_nums) <==> j in new_right_nums;
168					
169					assert forall j,k::0<=j < k < |new_right_nums| ==> new_right_nums[j] < new_right_nums[k];
170					assert x > i;
171					lemma_all_big(new_right_nums,i);
172					assert forall j::0<=j < |new_right_nums| ==> new_right_nums[j] > i;
173					
174					// assert Ascending(new_right_nums+[i]);
175					assert Ascending(Inorder(t));
176	
177					assert BST(t);
178				}
179			}
180		}
181	}
