183	lemma	LemmaBinarySearchSubtree(n: int, left: Tree, right: Tree)
184		requires BST(Node(n, left, right))
185		ensures BST(left) && BST(right)
186	{
187		assert Ascending(Inorder(Node(n, left, right)));
188		var qleft, qright := Inorder(left), Inorder(right);
189		var q := qleft+[n]+qright;
190		assert q == Inorder(Node(n, left, right));
191		assert Ascending(qleft+[n]+qright);
192		assert Ascending(qleft) by { LemmaAscendingSubsequence(q, qleft, 0); }
193		assert Ascending(qright) by { LemmaAscendingSubsequence(q, qright, |qleft|+1); }
194	}
195	
196	lemma LemmaAscendingSubsequence(q1: seq<int>, q2: seq<int>, i: nat)
197		requires i <= |q1|-|q2| && q2 == q1[i..i+|q2|]
198		requires Ascending(q1)
199		ensures Ascending(q2)
200	{}
201	
202	lemma {:verify true} lemma_all_small(q:seq<int>,i:int)
203		requires forall k:: k in NumbersInSequence(q) ==> k < i
204		requires forall k:: 0 <= k < |q| ==> q[k] in NumbersInSequence(q)
205		ensures forall j::0<=j < |q| ==> q[j] < i && j != 0
206	{}
207	
208	lemma {:verify true} lemma_all_big(q:seq<int>,i:int)
209		requires forall k:: k in NumbersInSequence(q) ==> k > i
210		requires forall k:: 0 <= k < |q| ==> q[k] in NumbersInSequence(q)
211		ensures forall j::0<=j < |q| ==> q[j] > i
212	{}

